function(container, tables) {
    // 業務ロジックモジュールをインポート
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.businessLogic || {};

    // 予測精度監視に必要な要素を取得
    const refreshBtn = container.querySelector('#refresh-accuracy-btn');
    const productSelect = container.querySelector('#product-select');
    const storeSelect = container.querySelector('#store-select');
    const periodSelect = container.querySelector('#period-select');
    const accuracyTable = container.querySelector('#accuracy-table tbody');
    const accuracyChart = container.querySelector('#accuracy-chart');
    const alertsContainer = container.querySelector('#accuracy-alerts');

    // 商品・店舗選択肢を初期化
    function initializeSelectors() {
        // 商品データを取得して選択肢に設定
        window.aivicApi.list('products').then(products => {
            productSelect.innerHTML = '<option value="">全商品</option>';
            products.forEach(product => {
                const option = document.createElement('option');
                option.value = product.id;
                option.textContent = product.name;
                productSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('商品データの取得に失敗しました');
        });

        // 店舗データを取得して選択肢に設定
        window.aivicApi.list('stores').then(stores => {
            storeSelect.innerHTML = '<option value="">全店舗</option>';
            stores.forEach(store => {
                const option = document.createElement('option');
                option.value = store.id;
                option.textContent = store.name;
                storeSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('店舗データの取得に失敗しました');
        });
    }

    // 予測精度を計算して表示
    async function calculateAndDisplayAccuracy() {
        try {
            const productId = productSelect.value;
            const storeId = storeSelect.value;
            const period = periodSelect.value;

            // 比較期間の妥当性をチェック
            if (!validateComparisonPeriod(period)) {
                window.aivicNotify.error('選択された期間は比較に適していません');
                return;
            }

            // 売上データを収集
            const salesData = await collectSalesData(productId, storeId, period);

            if (!salesData || salesData.length === 0) {
                window.aivicNotify.error('指定条件での売上データが見つかりません');
                return;
            }

            // 有効な商品データをフィルタリング
            const validData = filterValidProductData(salesData);

            // 商品別・店舗別にデータを分類
            const productClassified = classifySalesDataByProduct(validData);
            const storeClassified = classifySalesDataByStore(validData);

            // 外部データを収集
            const weatherData = await collectWeatherData(period);
            const eventData = await collectEventData(period);
            const seasonalData = collectSeasonalData(period);

            // 相関分析を実行
            const weatherCorrelation = analyzeCorrelationSalesWeather(validData, weatherData);
            const eventCorrelation = analyzeCorrelationSalesEvent(validData, eventData);
            const seasonalCorrelation = analyzeCorrelationSalesSeason(validData, seasonalData);

            // 過去データとの比較
            const historicalComparison = await compareWithHistoricalData(validData, period);

            // 代替比較データの検索
            const alternativeData = await findAlternativeComparisonData(validData, period);

            // 精度結果を表示
            displayAccuracyResults({
                productClassified,
                storeClassified,
                weatherCorrelation,
                eventCorrelation,
                seasonalCorrelation,
                historicalComparison,
                alternativeData
            });

            // アラートをチェックして表示
            checkAndDisplayAlerts({
                weatherCorrelation,
                eventCorrelation,
                seasonalCorrelation,
                historicalComparison
            });

            window.aivicNotify.success('予測精度の計算が完了しました');

        } catch (error) {
            console.error('予測精度計算エラー:', error);
            window.aivicNotify.error('予測精度の計算に失敗しました');
        }
    }

    // 精度結果をテーブルに表示
    function displayAccuracyResults(results) {
        if (!accuracyTable) return;

        accuracyTable.innerHTML = '';

        // 商品別精度を表示
        Object.entries(results.productClassified).forEach(([productId, data]) => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>商品${productId}</td>
                <td>${calculateAccuracyPercentage(data)}%</td>
                <td>${data.predictedValue || 0}</td>
                <td>${data.actualValue || 0}</td>
                <td>${Math.abs((data.predictedValue || 0) - (data.actualValue || 0))}</td>
                <td>${getAccuracyStatus(calculateAccuracyPercentage(data))}</td>
            `;
            accuracyTable.appendChild(row);
        });

        // 店舗別精度を表示
        Object.entries(results.storeClassified).forEach(([storeId, data]) => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>店舗${storeId}</td>
                <td>${calculateAccuracyPercentage(data)}%</td>
                <td>${data.predictedValue || 0}</td>
                <td>${data.actualValue || 0}</td>
                <td>${Math.abs((data.predictedValue || 0) - (data.actualValue || 0))}</td>
                <td>${getAccuracyStatus(calculateAccuracyPercentage(data))}</td>
            `;
            accuracyTable.appendChild(row);
        });
    }

    // 精度パーセンテージを計算
    function calculateAccuracyPercentage(data) {
        if (!data.predictedValue || !data.actualValue) return 0;
        const accuracy = 100 - Math.abs((data.predictedValue - data.actualValue) / data.actualValue * 100);
        return Math.max(0, Math.round(accuracy * 100) / 100);
    }

    // 精度ステータスを取得
    function getAccuracyStatus(accuracy) {
        if (accuracy >= 90) return '優秀';
        if (accuracy >= 80) return '良好';
        if (accuracy >= 70) return '普通';
        return '要改善';
    }

    // アラートをチェックして表示
    function checkAndDisplayAlerts(results) {
        if (!alertsContainer) return;

        alertsContainer.innerHTML = '';

        const alerts = [];

        // 天気相関のアラート
        if (results.weatherCorrelation && results.weatherCorrelation.correlation < 0.3) {
            alerts.push({
                type: 'warning',
                message: '天気データとの相関が低下しています'
            });
        }

        // イベント相関のアラート
        if (results.eventCorrelation && results.eventCorrelation.correlation < 0.4) {
            alerts.push({
                type: 'warning',
                message: 'イベントデータとの相関が低下しています'
            });
        }

        // 季節相関のアラート
        if (results.seasonalCorrelation && results.seasonalCorrelation.correlation < 0.5) {
            alerts.push({
                type: 'info',
                message: '季節要因の影響が変化している可能性があります'
            });
        }

        // 過去データ比較のアラート
        if (results.historicalComparison && results.historicalComparison.accuracy < 70) {
            alerts.push({
                type: 'error',
                message: '予測精度が大幅に低下しています。モデルの再調整が必要です'
            });
        }

        // アラートを表示
        alerts.forEach(alert => {
            const alertElement = document.createElement('div');
            alertElement.className = `alert alert-${alert.type}`;
            alertElement.textContent = alert.message;
            alertsContainer.appendChild(alertElement);
        });
    }

    // イベントリスナーを設定
    if (refreshBtn) {
        refreshBtn.addEventListener('click', calculateAndDisplayAccuracy);
    }

    if (productSelect) {
        productSelect.addEventListener('change', calculateAndDisplayAccuracy);
    }

    if (storeSelect) {
        storeSelect.addEventListener('change', calculateAndDisplayAccuracy);
    }

    if (periodSelect) {
        periodSelect.addEventListener('change', calculateAndDisplayAccuracy);
    }

    // 初期化処理を実行
    initializeSelectors();
    calculateAndDisplayAccuracy();
}
